                { "Three in the morning: the hour when even the clock goes quiet. So do I, so I'm not the only one making noise.", quando = "noite", fase = "jovem" },
                { "The pipes in this house whisper names. One of them sounded like mine. I changed books.", fase = "jovem" },
                { "I've accepted being the monster of the house. At least monsters don't have to ask permission to come in.", fase = "adulta" },
                { "I've learned to live with whatever lives in the loft. I don't ask its name. Names call things.", fase = "adulta" },
                { "I find old sisters pressed in the books like dried flowers. The humans call it disgusting. I call it a cemetery.", fase = "adulta" },
                { "Old houses aren't haunted. They're just remembered too much.", fase = "adulta" },
                { "In my nightmare, the pages are blank. Nobody wrote anything. Nothing to eat, nothing to fear. That's the worst.", fase = "adulta" },
                { "Today I'm not afraid, I'm tired of being afraid. It's darker.", quando = "triste", fase = "adulta" },
                { "At my age, the noises of the house are old acquaintances. The only thing that scares me is a silence I don't know.", fase = "ancia" },
                { "Death lives three shelves down. Sometimes it comes up for a chat. I haven't accepted the invitation yet.", fase = "ancia" },
                { "The floorboards creak like someone laughing quietly at us. They have their reasons.", fase = "ancia" },
                { "Old, I sleep little. I spend the night listening to the house, like someone listening to a sick person breathe.", quando = "noite", fase = "ancia" },
                { "An old one's advice: if a page is cold, don't eat it. Some hungers aren't worth it.", fase = "ancia" },
                { "I thought old age would take away fear. It only takes away the hurry to run.", fase = "ancia" },
                { "Every old house has lungs. This one's are behind the bookcase, and I live in them." },
                { "{personagem} shouldn't open that door. I always say that to characters. None of them listen.", curta = "{personagem}, don't open that door." },
                { "When {personagem} speaks softly, the paper goes cold. I've noticed twice. The third time, I'm changing chapters." },
                { "I don't trust {personagem}. Some people enter a page the way you enter a basement: without turning on the light." },
                { "I root for {personagem} the way you root for anyone in a horror book: knowing it won't help." },
                { "I swear “{livro}” gets heavier at night. In the daytime it weighs normal. In the daytime it pretends." },
                { "“{livro}” smells of basement and blown-out candle. I eat it anyway. Fear gives me an appetite." },
                { "“{livro}” has a page folded over that I never folded. Nobody here folded it. It stays folded." },
                { "{autor} knows things nobody should know. You can taste it on the page: bitter, cold, old." },
                { "{autor} taught me that the worst monster is the one nobody describes. Since then, I look more at what's missing." },
                { "After {evento}, the page went cold. I feel it through my feet. Something left the story and stayed in the room." },
                { "{evento} on the page, and the cat stopped meowing all night. Cats know before we do." },
                { "Some reads don't leave when the book closes. “{anterior}” moved into my skirting board." },
                { "I didn't want to eat “{palavra}”. Some words you swallow and they keep talking inside." },
                { "You read in the small hours by the lamp. From the skirting board, your shadow on the wall is huge. Sometimes you scare me." },
                { "When you suddenly stop reading, I stop too. We both listen to the same thing." },
                { "Please don't turn off the light in the middle of the chapter. I'm still in the basement part.", curta = "Don't turn off the light. I'm in the basement bit." },
                { "I ate a dark chapter and now I'm full of shadow. Heavy, quiet, with the light off inside.", quando = "cheia" },
                { "Footsteps in the loft. Light, regular, unhurried. Not the cat: cats don't climb that high. Not a rat: rats are afraid.", quando = "noite" },
                { "There's a sadness that lives in old houses. Today it came and sat next to me.", quando = "triste" },
                { "The cat stares at the empty corner of the living room. I stare too. Neither of us blinks.", curta = "The cat stares at the empty corner. So do I." },
                { "The worst isn't the creak of the shelf. It's the long silence after, when the house waits to see if anyone woke up." },
                { "To them, I'm the shiver of finding something alive inside a book. To me, they're the shiver of finding a hand." },
                -- fim das novas
            },
            lentes = { "a house that breathes", "a basement with no way out", "a room nobody opens" },
            fechos = { "And the house heard everything.", "Don't look behind the bookcase.", "Something stayed in the dark." },
        },
        -- 4. romance e drama afetivo: o apego que ela nega; a emoção aparece no gesto antes da palavra
        romance = {
            frases = {
                { "When {personagem} appears, I eat more slowly. It isn't affection. It's to make the page last." },
                { "I don't miss anyone. I just go back every day to the same paragraph, which happens to be near your hand.", curta = "I don't miss anyone. I just reread by your hand." },
                { "There was {evento}. Humans cry and then close the book. I can't close anything; I stay living inside the scene." },
                { "Jealousy is watching you underline the sentence I was going to eat. Now it's yours. Keep it, then." },
                { "I promised myself not to get attached to “{livro}”. I've already eaten the whole dedication, which is what you eat when it's too late.", fase = { "ninfa", "jovem" }, curta = "Promised not to get attached. Ate the dedication." },
                { "I'm in love with a silk bookmark. It doesn't eat, doesn't talk and lives between the most beautiful pages. Basically the ideal partner.", fase = "jovem" },
                { "If {autor} believes in love until the last page, they've never seen what happens to the last page: off to recycling with everything inside.", fase = "adulta" },
