                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I don't know how to love yet, but I already know how to come back to the same place every day. They say that's how it starts.", fase = "ninfa" },
                { "I found a letter inside a book. I didn't understand the words, but the paper smelled of a nervous hand.", fase = "ninfa" },
