                { "Jealousy is watching you open another book before finishing ours.", fase = "jovem", curta = "Jealousy: you opening another book first." },
                { "I sent a message through the crack in the bookcase. The reply came two days later: a crumb. I still keep it.", fase = "jovem" },
                { "In books, love has balls, letters and rain. On the shelf, it has a shared crumb and someone who doesn't run when you arrive.", fase = "jovem" },
                { "Today she ate right next to me. Nobody said anything. Best chapter of the year.", quando = "feliz", fase = "jovem" },
                { "Unrequited love tastes like glossy paper: it shines and doesn't nourish.", quando = "triste", fase = "jovem", curta = "Unrequited love: shiny, no nourishment." },
                { "I'm not in love. I just eat more slowly when she goes by, which is different.", fase = "adulta" },
                { "I keep grudges the way I keep crumbs: in a safe corner, for when I run out of things to talk about.", fase = "adulta" },
                { "Grown-up love is this: knowing where the other one sleeps and not making noise nearby.", fase = "adulta" },
                { "I never said I liked her. I just moved my hiding place closer.", fase = "adulta", curta = "Never said a word. Just moved closer." },
                { "We were made for each other, but on different bookcases. Is there a greater distance than that?", fase = "adulta" },
                { "Longing shows up at night because in the daytime I eat too much to think.", quando = "noite", fase = "adulta" },
                { "I've forgotten many books. I haven't forgotten the smell of the volume where I met her.", fase = "ancia" },
                { "Old, I've gone soft. I cry at every ending, even the ones that aren't about love.", fase = "ancia" },
                { "I want to leave slowly, like someone closing a book they really loved.", fase = "ancia" },
                { "An old one's advice: whoever shares the crumb shares the rest.", fase = "ancia" },
                { "Sad like a dedication to someone who's already gone.", quando = "triste", fase = "ancia" },
                { "When a book moves me, I stop eating. That's my way of crying." },
                { "I read {personagem}'s lines twice before eating them. Some I keep whole." },
