        -- 5. aventura e exploração: a casa como território sem mapa; a curiosidade empurrada pela fome
        aventura = {
            frases = {
                { "I went to the end of the hallway. There's a world out there: a rug like a desert, a skirting board like a coastline and a cat like the end of an expedition.", fase = { "ninfa", "jovem" }, curta = "Explored the hallway. Found a desert and a cat." },
                { "I mapped “{livro}” with my teeth: north is the cover, south is the flap, and in between there's a sea of pages nobody comes back from the same." },
                { "Between the skirting board and the rug there's a passage no human knows. I know it. It's my only property.", fase = { "adulta", "ancia" }, curta = "My only property: the passage by the skirting." },
                { "There was {evento}. I wrote it in my logbook, which is the margin of page forty. Great explorers had bad handwriting too.", curta = "There was {evento}. Wrote it in my logbook." },
                { "Today I found out the bookcase has another side. Nobody told me. The world is bigger than a book, and that makes me hungry.", fase = "ninfa" },
                { "I planned to cross the whole living room to the cardboard box in the laundry room. They say there's old newspaper there. They say nobody comes back. They say a lot.", fase = "jovem" },
                { "In a book, {autor} only has to write one line for someone to cross an ocean. I cross the living room and it's already an epic. Distance depends on the size of whoever walks it.", fase = "adulta" },
                { "I've been to the pantry, the garage and a suitcase that went on a plane. These days my longest trip is from the cover to the middle. Still worth it.", fase = "ancia" },
                { "I left my hiding place like someone setting off on {lente}. I came back with a crumb and a story I'll tell bigger than it was." },
                { "The greatest danger isn't the unknown. It's the known, holding a slipper.", fase = { "adulta", "ancia" } },
                { "I want to see the world. From a crack, ideally.", fase = { "ninfa", "jovem" } },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I crossed the rug for the first time. In the middle you can't see either edge. I felt what sailors feel.", fase = "ninfa" },
                { "I found out there's an “outside”. I don't know what it is yet. I already want to go.", fase = "ninfa" },
                { "I packed provisions for the journey and ate them all before leaving. It's part of the preparation.", fase = "ninfa" },
                { "The unknown smells of fresh dust. I like it. I'm scared. I'm going.", fase = "ninfa" },
                { "My first map has three places: here, there and the cat's place. The third has a skull on it.", fase = "ninfa" },
                { "I got into a suitcase that was travelling. I was away a week. I met a hotel, a beach and a soggy paperback.", fase = "jovem" },
                { "I was shipwrecked in a glass of water that spilled on the rug. I survived clinging to a napkin. I tell everyone.", fase = "jovem", curta = "Shipwrecked in a glass of water. True story." },
                { "My compass is hunger: it always points north, which is where the bread is.", fase = "jovem", curta = "My compass is hunger. It points to bread." },
                { "I travelled to the window at night. Outside there were lights, noises and a smell of rain I'd never eaten.", quando = "noite", fase = "jovem" },
                { "I've explored everything there is to explore in this house. Now I explore books, which have more rooms.", fase = "adulta" },
                { "I finished the map of the house. It took years. The next day they moved the furniture.", fase = "adulta" },
                { "Between danger and boredom, I choose danger. Boredom kills too, just more slowly.", fase = "adulta" },
                { "I miss the days when every room was a country. The house has got small. Or I've got big.", fase = "adulta" },
                { "There's one place in this house I went once and never again: the toolbox. Some journeys you only need once.", fase = "adulta" },
                { "My logbook says: day 412, still in the living room, food scarce, morale high.", fase = "adulta", curta = "Day 412. Still in the lounge. Morale high." },
                { "Sad like a map with every corner filled in.", quando = "triste", fase = "adulta" },
                { "I'm planning my last journey: from the bookcase to the window, to see the street once before the end.", fase = "ancia" },
                { "The world I explored doesn't exist anymore: they changed the bookcase, the curtain and the rug. My routes have become legends.", fase = "ancia" },
                { "An old explorer's advice: danger is never where it seems. It's on the polished floor.", fase = "ancia" },
                { "In the small hours I sit at the edge of the window, looking at the street. I've never been out there. That's the trip for another life.", quando = "noite", fase = "ancia" },
                { "Old, I still want to see what's on the other side of the door. Wanting is the last thing to grow old.", fase = "ancia" },
                { "This house is a continent: bookcase highlands, rug deserts and a sea of polished floor." },
                { "I wish I had {personagem}'s courage when the cleaning comes. I only have the hurry." },
                { "{personagem} is going too far. I know from experience: past the rug, nobody comes back the same." },
                { "{personagem} would carry the torch. I'd carry the crumb. We'd be unbeatable until the first cat." },
                { "“{livro}” is unexplored territory. I go in through the flap, the way explorers went in by the rivers." },
                { "I started “{livro}” like someone boarding a ship. I don't know where I'll get off yet." },
                { "In “{livro}” there's a point of no return. I passed it yesterday. No regrets." },
                { "{autor} draws paths I follow with my eyes shut. The best guides let you get a little lost." },
                { "In one line, {autor} has someone cross an ocean. It takes me an afternoon to cross the living room. I respect the technique." },
                { "There was {evento}, and the book's expedition got more dangerous. I ate faster, like someone stocking up on supplies." },
                { "I still tell stories about “{anterior}” like someone describing a faraway country. I exaggerate a little. It's my right." },
                { "I faced the hallway like {lente}. I crossed it. Nobody clapped. Great crossings are silent." },
                { "I found “{palavra}” in the middle of the page like finding an island on the map. I went ashore." },
                { "Exploring a book about {tema} is like entering a territory with no map. Everything is new, fear included." },
                { "You don't need to leave the house to go far. I learned that from you.", curta = "You can go far without leaving home." },
                { "You turn the pages like someone hoisting sails. I feel the wind." },
                { "When you close the book, it's like reaching port. I get off, breathe and wait for the next voyage." },
                { "Hunger is the best excuse for an adventure. Today it sent me all the way to the pantry.", quando = "fome" },
                { "At night, the lights on the living room gadgets are my stars. I navigate by them to the kitchen.", quando = "noite" },
                { "Sometimes the journey gets tiring and you just want to go back to a place that no longer exists.", quando = "triste" },
                { "The cat sleeps in the middle of the map. I go round the whole continent." },
                { "Out there there's rain, wind and books I'll never eat. I keep looking." },
                { "Curiosity is the only thing that grows faster than I do." },
                { "I come back from my travels hungry, tired and full of stories. The bookcase never asks. I tell it anyway." },
                -- fim das novas
            },
            lentes = { "an expedition without a map", "a crossing on the open sea", "a voyage round the world by bookcase" },
