        -- 7. realismo mágico e fantástico: o impossível contado com a calma de quem comenta o tempo
        magico = {
            frases = {
                { "It rained shredded paper in the kitchen on Tuesday. Nobody found it strange, and I stocked up, because miracles run out too.", curta = "Paper rained in the kitchen. Nobody minded. I ate." },
                { "My great-grandmother lived two hundred years inside an encyclopedia and died the day they took out volume H. To this day nobody in the family says that letter." },
                { "One day I woke up with wings. The next day, they were gone. Nobody mentioned it, and neither did I; some things only exist while nobody talks about them.", fase = { "ninfa", "jovem" }, curta = "One day I had wings. Then I didn't. Nobody said." },
                { "There was {evento}, and afterwards life went on as if nothing had happened. That's how impossible things happen: in the middle of the afternoon, with no music." },
                { "I was born on a night when the living-room lamp switched itself on. My mother said it was a sign. She didn't say of what. Mothers never do.", fase = "ninfa" },
                { "The word “{palavra}” floated above the page for three days. I walked under it every morning, like walking under a washing line.", fase = "adulta" },
                { "The dead on the bookcase keep giving their opinions in the margins. At my age, I answer back, and sometimes I win the argument.", fase = "ancia" },
                { "The dust in this house keeps what the people living here forgot. Today it told me {lente}, and I pretended I already knew." },
                { "When it rains, paper tastes like “{anterior}” again. The books you eat don't leave; they just move around inside you.", fase = { "adulta", "ancia" }, curta = "When it rains, old books come back to my tongue." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "The day I was born, the kitchen clock ran backwards for an hour. I've been running late ever since.", fase = "ninfa" },
                { "Today a word left the page and went for a walk on the rug. I followed. It came back before dinner.", fase = "ninfa" },
                { "Some words have colours. Yesterday I ate a blue “longing”. Today I woke up a little blue inside.", fase = "ninfa", curta = "I ate a blue word. I woke up blue." },
                { "My shadow goes out for walks on its own at night. It comes back smelling of other books.", fase = "ninfa" },
                { "I woke up with wings one Sunday. I flew to the window, looked at the street and came back. By Monday they were gone. Nobody mentioned it.", fase = "jovem" },
                { "The pages I eat grow back at the full moon. The whole bookcase knows. Humans never notice.", fase = "jovem" },
                { "It rained letters in the living room all afternoon. I gathered the ones that fell by the skirting board and stocked up for winter.", fase = "jovem", curta = "It rained letters. I stocked up." },
                { "I found my name written in pencil in a hundred-year-old book. I don't even have a name yet. Now I do.", fase = "jovem" },
                { "Inside this book time passes more slowly. I went in on a Monday and came out on a Thursday, not hungry.", fase = "jovem" },
                { "In the small hours, the characters from closed books climb down from the shelf to get some air. I greet them all. They pretend not to see me.", quando = "noite", fase = "jovem" },
                { "A ray of sun came exactly into my hiding place at three in the afternoon and stayed only there. I was warm and happy for no reason.", quando = "feliz", fase = "jovem" },
                { "In this house, the impossible happens every afternoon after coffee. Nobody mentions it, so as not to scare it away.", fase = "adulta" },
                { "This afternoon has happened before. Same light, same cup, same book open at the same page. I don't mind. It was a good afternoon.", fase = "adulta" },
                { "When someone sad walks into the room, the pages of the books go damp. The house cries in its own way.", fase = "adulta" },
                { "I ate the word “hope” and it stayed alive inside me, wriggling. It tickles.", fase = "adulta" },
                { "Every full moon, the whole bookcase turns silver like me. That night, nobody sees me. I'm the colour of the world.", fase = "adulta" },
                { "Today it rained only on me, indoors. A small private rain. Humans would call it a leak.", quando = "triste", fase = "adulta" },
                { "I'm so old that the ghosts on the shelf treat me as a colleague.", fase = "ancia" },
                { "When the time comes, I want to go like my great-grandmother: inside an open book, on a rainy afternoon, without a sound.", fase = "ancia" },
                { "In old age, time folds like an old page. Yesterday and today end up touching. Sometimes I eat both together.", fase = "ancia" },
                { "I teach the young ones to leave a crumb for the dead of the bookcase. They don't eat. But they feel remembered.", fase = "ancia" },
                { "At my age, if the book flies off, I only ask that it comes back before the cleaning.", fase = "ancia" },
                { "It rained confetti in the kitchen. Nobody found it strange. I took the chance to stock up.", curta = "It rained confetti. Nobody blinked." },
                { "I suspect {personagem} knows they're a character. They have a way of looking out of the page." },
                { "Every time {personagem} appears, the page gets warmer. I've stopped asking." },
                { "{personagem} lives in a time when anything can happen. Like this house at four in the afternoon." },
                { "When “{livro}” stays closed for a long time, the words rearrange themselves. You never read exactly the same story." },
                { "The photo of {autor} on the flap winked at me yesterday. I didn't tell anyone." },
                { "{evento} in the book, and at that very moment the living room clock stopped. It started again when I turned the page." },
                { "After {evento}, a flower grew in the dry vase in the living room. Nobody mentioned it." },
                { "When it rains, the paper tastes of “{anterior}” again. The books we eat don't leave; they move to another place inside us." },
                { "The whole afternoon looked like {lente}: beautiful, strange and smelling of something old." },
                { "The word “{palavra}” floated above the page for three days. I passed under it every morning, like walking under a ladder." },
                { "This book talks about {tema} the way old ladies talk about the weather: naturally, even when it's impossible." },
                { "The day you arrived with this book, the lamp flickered three times. It was a sign. I still don't know of what." },
                { "Sometimes you fall asleep with the book open on your chest, and the story carries on by itself. I read the rest for you." },
                { "You'll never know, but the books you read keep your smell for years. I recognise it." },
                { "Today hunger tastes of memory. I ate a page and missed my grandmother.", quando = "fome" },
                { "At three in the morning, a blue light wanders along the shelf and stops above the book you'll read tomorrow.", quando = "noite" },
                { "Sad like a legend nobody tells anymore.", quando = "triste" },
                { "The house cat is seven hundred years old. Nobody tells. Neither does the cat." },
                { "I don't try to explain what I see. Explanations spoil the taste.", curta = "I don't explain things. It spoils the taste." },
                { "The world is full of impossible things. Most of them happen on Tuesday afternoons." },
                -- fim das novas
            },
            lentes = { "a household miracle", "a rain that doesn't wet", "a story the family has repeated for generations" },
            fechos = { "Nobody found it strange.", "And the house stayed the same.", "It was all very natural, unfortunately." },
