        -- 8. sátira e comédia: a vaidade e as convenções vistas de baixo, sem levantar a voz
        satira = {
            frases = {
                { "Humans diet, count calories and weigh their flour. I'm the one eating paper in moderation, and I'm still the pest.", curta = "Humans go on diets, and I'm the pest." },
                { "They invented the library to keep readers' books, and the padlock to keep the library's books. I get in through the middle, which nobody locks." },
                { "If {autor} has a photo on the jacket flap, I bet they're gazing at the horizon. They all do. My horizon is just past the shelf." },
                { "Every story has someone who takes themselves too seriously. Here, I suspect {personagem}. But I take myself seriously too, and I live in a book." },
                { "Life's first lesson: a classic is a book everyone owns and nobody opens. Excellent. More food for me.", fase = "ninfa" },
                { "I went to a book club hidden in the lining of an armchair. They discussed the wine, the cover and someone's ex. The book was left out. Like me.", fase = "jovem" },
                { "This book talks about {tema} with the solemnity of someone who never had to hide behind a skirting board. I respect it, from a distance, with my mouth full.", fase = "adulta" },
                { "I've seen three 'forever' bookcases in this house. The first became firewood, the second went to a thrift shop, the third is this one. Everything that's forever feeds me.", fase = "ancia" },
                { "The humans called it a renovation. I'd call it {lente}: noise, dust and no consultation with the old residents.", fase = { "adulta", "ancia" }, curta = "They called it a renovation. Nobody asked me." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "First observation about humans: they have shelves for books they don't read and phones for books they don't buy.", fase = "ninfa" },
                { "First lesson in good manners: you don't eat a dedication in front of others.", fase = "ninfa" },
                { "Visitors came today. They tidied the bookcase, put the nice books at the front and hid the self-help. I learned what shame is.", fase = "ninfa" },
                { "I found out I have a scientific name in Latin. Humans hate me, but they gave me an emperor's name.", fase = "ninfa" },
                { "I read the back covers of three books. All of them were “unmissable”. I ate one, so as not to miss it.", fase = "ninfa" },
                { "I went to the book club hidden in the armchair lining. They discussed the wine, the cheese and somebody's ex. The book was saved for next time.", fase = "jovem" },
                { "There's a bookcase in the living room with books chosen by colour. The yellow ones sit together. Literature has become a palette.", fase = "jovem" },
                { "Some people read the summary and discuss the book. I eat the book and discuss nothing. Which of us is more cultured?", fase = "jovem" },
                { "I ate the preface to a book about humility. Eighteen pages about the author. The irony made my day.", quando = "feliz", fase = "jovem" },
                { "Small hours: the time when self-help books feel insecure.", quando = "noite", fase = "jovem" },
                { "They built a home office to work in. Now they work in the kitchen and the office stores boxes.", fase = "adulta" },
                { "They started the diet on Monday. On Tuesday there were biscuit crumbs behind the sofa. I don't report it. I'm grateful.", fase = "adulta" },
                { "They arranged the bookcase alphabetically. It lasted a week. Then the natural order came back: laziness.", fase = "adulta" },
                { "They donated a box of books “to make space”. The space was filled by a plastic plant.", fase = "adulta" },
                { "I watched an expert on TV say that nobody reads anymore. Judging by the look, neither does the expert.", fase = "adulta" },
                { "They promised to read more this year. They bought twelve books. I'm the only one meeting the target.", fase = "adulta", curta = "They vowed to read more. Only I do." },
                { "Sad like a joke told at the wrong moment.", quando = "triste", fase = "adulta" },
                { "I watched colouring books for adults arrive and leave. Nobody coloured anything. I ate the mandalas.", fase = "ancia" },
                { "Old age gave me the right to yawn at any preface.", fase = "ancia" },
                { "I've known humans who read and humans who bought. Never the same ones.", fase = "ancia" },
                { "At the launch party, the book stayed closed on the table, like decoration on the cake.", fase = "ancia" },
                { "At my age, criticism is simple: if I finish it, it's good.", fase = "ancia" },
                { "Night is the best time to laugh at humans. They don't hear and don't take offence.", quando = "noite", fase = "ancia" },
                { "People take photos of the cup next to the book. The book stays in the background, like furniture." },
                { "Every story has someone who takes themselves too seriously. Here, I suspect {personagem}. But I take myself seriously too, and I live in a skirting board." },
                { "{personagem} would be a hit at the book club: talks a lot and already has an opinion before reading." },
                { "{personagem} has too many good manners. I distrust anyone who never leaves crumbs." },
                { "“{livro}” has praise on the back from people who probably didn't read it. I read it. I ate it. I'm the critic." },
                { "If {autor} has a photo on the flap, I bet it's gazing at the horizon. They all do. My horizon is just past the skirting board." },
                { "{autor} wrote for posterity. Posterity, around here, is me." },
                { "{evento}, and still someone worried about their clothes. Vanity survives everything." },
                { "After {evento}, everyone got together to eat. That's how humans deal with everything." },
                { "After “{anterior}”, I learned to distrust anyone who takes themselves seriously on the first page." },
                { "Today's visit looked like {lente}. Everyone talking, nobody listening, and me on the skirting board, taking notes." },
                { "“{palavra}” is the kind of word you use at parties to impress. I use it at breakfast." },
                { "You show the book to the camera like someone introducing an important relative. I prefer it when you just read." },
                { "You don't have a decorative bookcase. The books on your shelf have been opened. It's an honour to live here." },
                { "You don't have a reading target. You just read. To me, that's the height of elegance." },
                { "When I'm hungry, I'd even eat a self-help book. Today I ate two.", quando = "fome" },
                { "Belly full of bestseller. Light and no nutrients.", quando = "cheia", curta = "Full of bestseller. Light, no nutrients." },
                { "At night the bookcase takes off its make-up. Just paper and dust, honest.", quando = "noite" },
                { "Sad like a party where everyone talks about books and nobody has read them.", quando = "triste" },
                { "Rare books are locked up so nobody damages them. That way nobody reads them either. Problem solved." },
                { "I'm the only one in this house who consumes culture every day. And I'm the pest.", curta = "I'm the only daily reader here. And the pest." },
                -- fim das novas
