        -- 11. realismo social: classe, trabalho, quem é dono da estante e quem limpa depois
        social = {
            frases = {
                { "Expensive books live in the glass bookcase. Cheap books live in the box in the garage, under the leak. I live in the garage: the food is worse, but nobody pretends it's culture." },
                { "Whoever binds doesn't read, whoever reads doesn't own, whoever owns doesn't read, and whoever eats gets exterminated. That's the paper food chain.", curta = "Readers don't own. Eaters get exterminated." },
                { "I work all night, no wages, no holidays, no light, and when they find me they call me a parasite. A parasite is someone with thirty books who reads one.", fase = { "adulta", "ancia" }, curta = "A parasite owns thirty books and reads one." },
                { "{autor} signed the book and kept the name. Whoever sewed, glued and carried the boxes doesn't appear on any page. I eat in their honour." },
                { "I keep wondering who washed the clothes of {personagem}. No book says. Other people's hunger always stays at the back of the scene." },
                { "I learned early: the top shelf is for the beautiful books, and the bottom one is for what's left over. I was born on the bottom one. It's a start.", fase = "ninfa", curta = "Born on the bottom shelf. It's a start." },
                { "This book talks a lot about {tema}. I'd like to know who paid for the paper, who carried the boxes and who cleaned up afterwards.", fase = "adulta" },
                { "There was {evento}. I bet whoever cleaned up afterwards doesn't appear on any page, not even in a footnote." },
                { "They called it a big clean. I'd call it {lente}: they decided for us, without asking, and thought they were doing us a favour." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "My mother raised thirty daughters in a newspaper box. Nobody wrote about it.", fase = "ninfa" },
                { "I'd barely hatched before I went to fetch food. There's no childhood in the garage box.", fase = "ninfa" },
                { "I found out that the very thing that feeds my family is called “damage” by the owners.", fase = "ninfa" },
                { "Garage hunger is different from bookcase hunger. One is lack. The other is choice.", fase = "jovem" },
                { "Night is the shift of those who have no choice.", quando = "noite", fase = "jovem" },
                { "Today we found a forgotten box of books. Food for the whole garage for a month. Nobody ate alone.", quando = "feliz", fase = "jovem" },
                { "Nobody sees whoever cleans the house at six in the morning. I do. We're the invisible work around here.", fase = "adulta" },
                { "The owners talk about books the way they talk about property: they value, invest, keep.", fase = "adulta" },
                { "The owner inherited grandpa's library and never opened a book. I inherited the garage and read everything.", fase = "adulta" },
                { "Humans call it a donation. We call it an eviction.", fase = "adulta" },
                { "Every book has a factory behind it, a print shop and someone on the night shift. The cover only has one name.", fase = "adulta" },
                { "Sad like a strike nobody noticed.", quando = "triste", fase = "adulta" },
                { "I've worked my whole life and I still live in the skirting board. I'm not complaining. I'm keeping a record.", fase = "ancia" },
                { "I took part in three attempts to occupy the glass bookcase. On the last one we won a shelf. It was worth it.", fase = "ancia" },
                { "I leave one idea as my inheritance: the bookcase belongs to whoever eats it.", fase = "ancia", curta = "The bookcase belongs to its eaters." },
                { "The house has neighbourhoods: the glass bookcase is the rich centre, the garage is the outskirts, the skirting board is the squat." },
                { "Every time {personagem} has coffee, somebody made the coffee. The book forgets. I don't." },
                { "{personagem} has never had to think about food. You can taste it on the page." },
                { "Does {personagem} work in this story? If so, the book doesn't show it. It's like that with almost everyone in books." },
                { "{personagem} makes choices as if they had a choice. I know not everyone does." },
                { "The cover of “{livro}” is luxury. The pages are economy class. Like a lot of people." },
                { "The price of “{livro}” is printed on the back. The price paid by whoever made it, nowhere." },
                { "“{livro}” lives on the middle shelf. Middle-class book: neither shop window nor box." },
                { "{autor}'s name is on the cover in big letters. The proofreader's is in small print inside. The printer's, nowhere." },
                { "I thank {autor} for looking down. Few do." },
                { "{evento}, and still someone had to serve dinner." },
                { "There was {evento}, and the ones who paid were the ones who always pay." },
                { "After “{anterior}”, I learned to look for who's working in the background of every scene." },
                { "The living room renovation was {lente}: nobody who lives on the bookcase was consulted." },
                { "“{palavra}” is a word for someone who has never carried a box." },
                { "Talking about {tema} is easy when you have a house. I read from down here, where the subject arrives with a leak." },
                { "You read after a whole day's work. I know what that costs." },
                { "You lend books. In this house, that's almost revolutionary." },
                { "You share books, I share crumbs. Each class with its own solidarity." },
                { "I'm hungry, and the glass bookcase is full. That isn't nature. It's organisation.", quando = "fome" },
                { "Full belly today. I'll save the rest for my sisters in the garage.", quando = "cheia" },
                { "Sad like a box of books going to the bin with a family inside.", quando = "triste" },
                { "Every book went through a print shop, and at the print shop someone was on shift. The smell of ink still keeps the tiredness." },
                { "If the bottom shelf falls, the whole bookcase falls. Nobody remembers that at the meetings." },
                { "The word “pest” was invented by those who had something to protect.", curta = "Pest: a word for those with things to guard." },
