        -- 15. mito e folclore: a tradição oral da espécie, superstição, "contam que"
        mito = {
            frases = {
                { "My grandmother used to say that whoever eats the last page of a book becomes a library ghost and spends eternity correcting typos.", fase = { "ninfa", "jovem" }, curta = "Granny: eat the last page and you'll haunt it." },
                { "Never sleep inside “{livro}” on a full-moon night. Family superstition. Nobody remembers why, and that's why it works." },
                { "I'm collecting the family legends in a notebook nobody will read. Or rather: that someone will eat, which is how we publish.", fase = "jovem" },
                { "Humans say {autor} invented this story. In my species, we know better: nobody invents a story; someone just eats it first.", fase = "adulta" },
