        -- 16. psicologia e introspecção: ela se observa, desconfia dos próprios motivos, lembra
        psicologia = {
            frases = {
                { "I noticed I always eat the margin before the text. It must be fear of getting to what matters. Or a hunger for edges. I haven't picked a diagnosis yet.", curta = "I start with the margin. Fear of the middle." },
                { "I say I'm not afraid of anything, and I always sleep with my back to the wall. One of those is a lie, and it isn't the wall.", fase = { "jovem", "adulta" }, curta = "Afraid of nothing. Back to the wall, though." },
